internal sealed interface Operation                  // sealed: the mediated surface is closed
internal data class Read(val id: ObjectId) : Operation
internal data class Write(val id: ObjectId, val value: String) : Operation
internal class ReferenceMonitor(private val policy: PolicyStore) {
    fun decide(subject: Subject, op: Operation): Decision {
        val principal = subject.principal ?: return Decision.Deny("no principal")
        return when (op) {                           // no else: a new Operation breaks the build
            is Read -> policy.allows(principal, op.id, Access.READ)
            is Write -> policy.allows(principal, op.id, Access.WRITE)
        }
    }
}
